function typeCounts(obj) {
  const counts = {};
  for (const key in obj) {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) continue;
    const type = obj[key] === null ? "null" : typeof obj[key];
    counts[type] = (counts[type] || 0) + 1;
  }
  return counts;
}
